    ["As Awe'ohna did, aid the fungarians and rutaani by slaying the creatures who have been frenzied by the damage caused by the darkened sky."] = "Як це робила Аве'огна, допоможи фунґаріанам і рутаані, убивши створінь, яких звело з розуму лихо від потьмянілого неба.",
    ["As Obayo once did, pour the last of the Echoless Flame's power into the Shul'ka wards and contain the monstrosity known as Morta'ka."] = "Як колись зробив Обайо, влий останок сили Беззвучного Полум'я в обереги Шул'ка і стримай потвору на ім'я Морта'ка.",
    ["As Two-Faced As They Come"] = "Дволикіший годі шукати",
    ["As the goblins were exposed to kaja'mite, they became aware of their own intelligence, soon using it to invent tools--and weapons."] = "Коли ґобліни зазнали впливу каджа'міту, вони усвідомили власний розум і невдовзі заходилися винаходити знаряддя — і зброю.",
    ["Ascend Black Rook Hold to track the risen Lord Ravencrest."] = "Зійди Твердинею Чорного Грака, щоб вистежити повсталого лорда Рейвенкреста.",
    ["Ascend into the gates of Niskara."] = "Зійди до брами Ніскари.",
