    ["Kruul's Intentions"] = "Наміри Круула",
    ["Kvaldir wards bar the way further into the swamp. Investigate Tideskorn Harbor to find a way through."] = "Обереги квалдирів перекривають шлях углиб болота. Дослідь гавань Тайдескорн, щоб знайти прохід.",
    ["Lady Selen'vjar had a treasure trove of ritual knowledge and artifacts that could hold valuable research and rewards."] = "У леді Селен'в'яр був скарб ритуальних знань і артефактів, що можуть містити цінні дослідження та винагороди.",
    ["Lady Selen'vjar is furious at the interference in her ritual. Her Mindbreaker was going to be her vanguard, but she is more than happy to take care of interlopers herself."] = "Леді Селен'в'яр розлючена втручанням у її ритуал. Її Розумоломець мав стати її авангардом, але вона радо й сама розбереться з непроханими гостями.",
    ["Lady Selen'vjar's captains are keeping the ritual grounds protected, while their other forces drain the essence from some wayward void creatures caught in Selen'vjar's grasp."] = "Капітани леді Селен'в'яр охороняють ритуальні землі, поки інші їхні сили висмоктують есенцію з блукливих створінь Порожнечі, що потрапили в лабети Селен'в'яр.",
