    ["Lockdown Mess"] = "Гармидер Локдауну",
    ["Long before the arrival of the Light, followers of the Old Gods darkened these caverns with their maddening misdeeds."] = "Задовго до приходу Світла прибічники Прадавніх Богів затьмарили ці печери своїми згубними злодіяннями.",
