    ["Meet Thisalee near Rhut'van Peak"] = "Зустрінься з Тісалі поблизу Піка Рут'ван",
    ["Meet Up with Thisalee"] = "Зустрінься з Тісалі",
    ["Meet Wrathion at the magical barrier in the Vault of the Shadowflame."] = "Зустрінься з Вратіоном біля магічного бар'єру у Сховищі Тіньового Полум'я.",
    ["Meet Yrel at the Karabor Harbor"] = "Зустрінься з Ірель у Гавані Карабор",
