    ["Mending Your Wounds"] = "Лікування ран",
    ["Mephistroth"] = "Мефістрот",
    ["Mephistroth has escaped but the skull is intact. Take it."] = "Мефістрот утік, але череп цілий. Забери його.",
    ["Mephistroth has escaped with the skull. Find a way across his trap and chase after him!"] = "Мефістрот утік із черепом. Знайди шлях крізь його пастку й пуститься навздогін!",
    ["Mephistroth has sent his minions after you. Survive their assault until Lady Tyrana and Pain Mistress Nikta arrives, then kill them."] = "Мефістрот наслав на тебе своїх посіпак. Витримай їхній натиск, доки не прибудуть леді Тирана та Володарка Болю Нікта, а тоді вбий їх.",
    ["Meryl is here preparing for the assault. Speak with him and Alodi to begin preparations."] = "Меріл тут готується до штурму. Поговори з ним та Алоді, щоб почати приготування.",
