    ["More creatures made from Stygia have emerged."] = "З'явилося ще більше створінь, зроблених зі стигії.",
    ["More wardstones will be needed to breach the wall. Collect more wardstones from the kvaldir in the harbor."] = "Щоб пробити стіну, знадобиться більше оберегових каменів. Збери ще оберегових каменів у квалдирів у гавані.",
    ["Mount Kalecgos atop the ridge at the Vermillion Redoubt."] = "Осідлай Калекґоса на хребті біля Багряного Редуту.",
