    ["Mount the Sunreaver Bloodhawk and fly with Scout Captain Elsia over the island."] = "Осідлай кривавого яструба Санріверів і пролети з капітаном-розвідницею Елсією над островом.",
    ["Mount the Trained Flayedwing to fly to the top of the falls."] = "Осідлай навченого білокрила, щоб злетіти на вершину водоспаду.",
    ["Mount your Thunderwing!"] = "Осідлай свого Громокрила!",
    ["Mountain Menace"] = "Гірська загроза",
    ["Move ahead through the Warsong onslaught. Regroup with the Alliance forces up the path and speak with Vindicator Yrel."] = "Пробийся крізь натиск Бойової Пісні. Перегрупуйся з силами Альянсу далі шляхом і поговори з відплатником Ірель.",
    ["Move ahead through the Warsong onslaught. Regroup with the Horde forces up the path and speak with Durotan."] = "Пробийся крізь натиск Бойової Пісні. Перегрупуйся з силами Орди далі шляхом і поговори з Дуротаном.",
    ["Moving on up"] = "Рух угору",
    ["Mug'Zee runs security within the Gallagio, Gallywix's impenetrable casino. No one gets to The Chrome King without going through this powerful ogre."] = "Муґ'Зі очолює охорону в «Ґалладжіо» — неприступному казино Ґаллівікса. Ніхто не дістанеться Хромового Короля, не пройшовши повз цього могутнього оґра.",
    ["Murloc Migration"] = "Переселення Мурлоків",
    ["Muse Wanted: Davenport Silli"] = "Потрібна муза: Девенпорт Сіллі",
    ["Music from Beyond the Grave"] = "Музика з-за могили",
    ["Mutations For All"] = "Мутації для всіх",
    ["Mutual Destruction"] = "Взаємне знищення",
