    ["Mycomancer Cavern"] = "Печера Мікоманта",
    ["Nagaz needs \"help with something\", probably a trap. Wait for him to spring it, then turn the tables."] = "Наґазу потрібна «допомога з дечим», імовірно, це пастка. Зачекай, доки він її захлопне, а тоді переграй його.",
    ["Narrow Escape"] = "На волосину від загибелі",
    ["Nasz'uro, the Unbound Legacy, is yours!"] = "Назз'уро, Звільнена Спадщина, тепер твій!",
    ["Naval Supremacy"] = "Морська перевага",
    ["Nek'zali the Soulcoiler once again threatens to unleash untold horrors upon Azeroth."] = "Нек'залі Душозмій знову погрожує наслати на Азерот незліченні жахіття.",
    ["Neltharion's Lair"] = "Лігво Нелтаріона",
    ["Neltharion's Shadow"] = "Тінь Нелтаріона",
    ["Neltharus"] = "Нелтарус",
    ["Network the Engine of Nalak'sha to the Chamber of Heart."] = "Під'єднай Двигун Налак'ши до Палати Серця.",
    ["Neutralizing the Contaminant"] = "Знешкодження забруднювача",
    ["Never a King"] = "Так і не король",
