    ["The Yaungol attack!"] = "Яунголи нападають!",
    ["The Zandalari have spotted you! Defeat your attackers!"] = "Зандалари помітили тебе! Здолай нападників!",
    ["The Zaqali ruins have been infested by hostile wildlife. Clear the area to allow the researchers to investigate."] = "Руїни Закалі заполонила ворожа звірина. Зачисти місцевість, щоб дослідники могли все вивчити.",
    ["The automated defenses of Gnomeregan have been activated!"] = "Автоматичну оборону Ґномреґана активовано!",
    ["The battle has ended, Flame's Radiance is withdrawing."] = "Битва скінчилася, Сяйво Полум'я відступає.",
    ["The battle is won, but what of Tyrande?"] = "Битву виграно, але що з Тірандою?",
    ["The beast has fled to another lair of mist, trap it again and avenge Wuho."] = "Звір утік до іншого туманного лігва. Знову залови його й помстися за Вухо.",
    ["The broken seal beckons from the lake bottom. Enter the Tomb of Tyr."] = "Зламана печатка вабить із дна озера. Увійди до Гробниці Тіра.",
    ["The cartels usually fought with gold--but when they fought with guns, they brought the big ones."] = "Картелі зазвичай билися золотом — та коли вже бралися за зброю, діставали найбільшу.",
    ["The cave howls. The only way is forward."] = "Печера завиває. Єдиний шлях — уперед.",
    ["The city must be put to the sword."] = "Місто має бути віддане під меч.",
    ["The corrupter has finally appeared. Slay Soth'ozz and complete the cleansing of the tomb."] = "Осквернитель нарешті з'явився. Убий Сот'озза й заверши очищення гробниці.",
    ["The cultists have breached the tomb of an ancient titan keeper! Slay the guards and open the way into the complex."] = "Культисти вломилися до гробниці прадавнього хранителя-титана! Перебий вартових і відкрий шлях до комплексу.",
    ["The cultists have entered a tomb complex at the bottom of the lake. The ritual must be happening in there."] = "Культисти проникли до гробничного комплексу на дні озера. Ритуал, певно, відбувається саме там.",
    ["The curse of Ula'tek surges forth. Prepare yourself!"] = "Прокляття Ула'тек наринає. Готуйся!",
    ["The defenses are active, but one final nightmare has appeared to block your path. It must be defeated."] = "Оборона діє, та постало останнє жахіття, щоб заступити тобі шлях. Його треба здолати.",
    ["The draenei house shimmers into existence. A figment of the imagination?"] = "Дренейський будинок мерехтливо постає з небуття. Витвір уяви?",
    ["The earthen, alongside other Titanforged creatures, tore into Azeroth's side, shaping the world into its current form."] = "Землероджені разом з іншими титанорідними створіннями розпанахали бік Азерота, надавши світові його теперішнього вигляду.",
    ["The elements are attacking! Protect our site from their aggression!"] = "Стихії нападають! Захисти нашу ділянку від їхньої агресії!",
    ["The elements begin churning"] = "Стихії починають вирувати",
    ["The elements begin churning."] = "Стихії починають вирувати.",
    ["The essences of Malygos and Sindragosa have been moved within the Azure Vault. It is time to release them!"] = "Есенції Малігоса й Синдрагоси перенесено до Лазурового Сховища. Час вивільнити їх!",
    ["The final fight"] = "Останній бій",
    ["The forces of Ula'tek were victorious. This event has been lost."] = "Сили Ула'тек перемогли. Цю подію програно.",
    ["The forces of the Nightmare have been defeated. The claws are now yours for the taking."] = "Сили Жахіття переможено. Тепер кігті — твої, бери.",
    ["The foul beast is dead and the path to the Spear is open. Take up Talonclaw."] = "Мерзенний звір мертвий, і шлях до Списа відкрито. Візьми Кіготь-Пазур.",
    ["The ghost has much information. Follow Thoradin and listen to his tale."] = "Привид знає чимало. Іди за Торадіном і вислухай його оповідь.",
    ["The ghost of Thoradin is being tortured by the cultists. Slay the ritualists and free him."] = "Культисти катують привида Торадіна. Убий ритуалістів і визволи його.",
    ["The giant aberration has the piece. Slay it and retrieve the piece."] = "Велетенська аберація має уламок. Убий її та забери уламок.",
    ["The goblins are attacking! Take down the Skyscorchers."] = "Ґобліни нападають! Знищ Небопалів.",
    ["The goblins were forced by the Zandalari Empire to mine kaja'mite, carving out the cavern that would one day become Undermine."] = "Зандаларська імперія змусила ґоблінів видобувати каджа'міт, видовбуючи печеру, що колись стане Андермайном.",
    ["The hearth is getting too hot!"] = "Вогнище стає надто гарячим!",
    ["The key to lifting the curse of this place rests in the final death of Darkmaster Gandling."] = "Ключ до зняття прокляття цього місця — в остаточній смерті Темного Володаря Ґандлінґа.",
    ["The kobyss and naga traded blows in battle for generations. Of all the ankoan tribes, only the kobyss matched the viciousness and violence of Azshara's armies."] = "Кобіси й наги обмінювалися ударами в битвах поколіннями. З усіх анкоанських племен лише кобіси не поступалися лютістю й жорстокістю військам Азшари.",
    ["The kvaldir are enraged at the loss of the mists. Survive their assault until the commanding helarjar arrives, then kill him."] = "Квалдири розлючені втратою туманів. Витримай їхній натиск, доки не прибуде командир-геларіар, а тоді вбий його.",
    ["The land quakes and the cold wind howls. Something is stirring in a nearby cave."] = "Земля двигтить, і холодний вітер виє. Щось ворушиться в сусідній печері.",
    ["The last remaining oaf in the Deadmines won't let you pass."] = "Останній бовдур у Мертвих Копальнях не пропускає тебе.",
    ["The last traces of the contaminant have coalesced into a hostile elemental that must be destroyed."] = "Останні сліди забруднювача злилися у ворожого елементаля, якого треба знищити.",
    ["The manifest indicates that the target is in Baradin Hold. Go there with Allaris and find the creature."] = "Опис вантажу вказує, що ціль — у Фортеці Барадін. Вирушай туди з Алларісом і знайди створіння.",
    ["The manifest isn't here, time to continue the search elsewhere."] = "Опису вантажу тут немає, час шукати деінде.",
    ["The massive void terror has consumed the Eye. Kill it to retrieve the Eye."] = "Велетенський жах Порожнечі поглинув Око. Убий його, щоб забрати Око.",
    ["The masters of the Peak of Serenity have gathered for a conclave."] = "Майстри Піка Безтурботності зібралися на конклав.",
    ["The might of the Warsong clan rests in their wolfriders. Flank the packmaster and the core of the clan's power will crumble."] = "Міць клану Бойової Пісні — у його вершниках на вовках. Обійди ватажка зграї з флангу, і осердя сили клану розсиплеться.",
    ["The naga are summoning a creature from the deeps, slay them!"] = "Наги викликають створіння з глибин — убий їх!",
    ["The only option is to jump!"] = "Єдиний вихід — стрибати!",
    ["The paint has come to life! Squish the paint blobs before they get out of hand."] = "Фарба ожила! Розчав фарбяні згустки, доки не вийшли з-під контролю.",
    ["The palatial grounds of the Nighthold stand as the pinnacle of a culture thoroughly shaped - and twisted - by magic."] = "Палацові угіддя Нічної Твердині — вершина культури, повністю сформованої й спотвореної магією.",
    ["The portals have stabilized, allowing access to the void forces' ritual chambers that were feeding the obelisks with power."] = "Портали стабілізувалися, відкривши доступ до ритуальних палат сил Порожнечі, що живили обеліски силою.",
    ["The power of the Fangs has driven Verstok insane. Subdue him."] = "Сила Іклів довела Верстока до божевілля. Угамуй його.",
    ["The power of the Grove of Awakening is ours once more! Return to the Winterqueen then vanquish Gorak Zhar!"] = "Сила Гаю Пробудження знову наша! Повернися до Зимової Королеви, а тоді розбий Ґорака Жара!",
    ["The primalists are swarming the World Tree in droves. Defend it!"] = "Первісники роями налягають на Світове Дерево. Захисти його!",
    ["The prison entrance is blocked with corruption. Cleanse the tomb of the corrupting void tendrils."] = "Вхід до в'язниці перекрито скверною. Очисти гробницю від оскверняючих щупалець Порожнечі.",
    ["The remaining Council aspirants have been greatly thinned. Meet up with the survivors and find out their plans."] = "Лави решти претендентів Ради значно проріділи. Зустрінься з тими, хто вцілів, і дізнайся їхні плани.",
    ["The ritual has been thwarted, but void energy remains! Defeat it!"] = "Ритуал зірвано, але енергія Порожнечі лишилася! Здолай її!",
    ["The ritual is nearly complete! Protect Lea from a final wave of invaders."] = "Ритуал майже завершено! Захисти Лею від останньої хвилі загарбників.",
    ["The ritual will begin shortly."] = "Ритуал скоро почнеться.",
    ["The rutaani and fungarians war with each other ceaselessly. By fang and claw, put an end to the conflict."] = "Рутаані й фунґаріани воюють між собою без упину. Іклом і кігтем поклади край цьому конфлікту.",
    ["The scribes are trapped within Scrollkeeper's Sanctum. Break in and rescue them!"] = "Писарів ув'язнено в Святилищі Хранителя Сувоїв. Удерися всередину й порятуй їх!",
    ["The servants of the Lich King have conjured walls of ice to block your path. Destroy them."] = "Слуги Короля-Ліча наврочили крижані стіни, щоб заступити тобі шлях. Знищ їх.",
    ["The shadows within Xylem have been let loose! Protect Xylem as he restores the ley energy to Azeroth."] = "Тіні всередині Зайлема вирвалися на волю! Захищай Зайлема, поки він відновлює лей-енергію Азерота.",
    ["The show is starting! Get to the stage!"] = "Вистава починається! Біжи на сцену!",
    ["The skull is yours! Step through its portal to depart this place."] = "Череп твій! Ступи крізь його портал, щоб покинути це місце.",
    ["The skull should be within Felsoul Hold. Make your way down the path and search for it."] = "Череп має бути у Фортеці Сквернодуш. Спустися стежкою й знайди його.",
    ["The spectacle at Bilgewater Flats is meant to distract the masses from Gallywix's boot on their necks. Quiet the noise pollution and free Undermine from Rik Reverb's influence."] = "Видовище на Рівнинах Трюмної Води має відвернути увагу мас від чобота Ґаллівікса на їхніх шиях. Угамуй шумове забруднення й визволи Андермайн з-під впливу Ріка Реверба.",
    ["The spike in energy has attracted forces from beyond the storm!"] = "Сплеск енергії привабив сили з-поза шторму!",
    ["The spirit of Traitor's Rest is attacking! We must protect the site to dig another day!"] = "Дух Спочинку Зрадника нападає! Ми мусимо захистити розкоп, щоб копати й надалі!",
    ["The streets around the Incontinental Hotel need a good sweeping!"] = "Вулиці навколо готелю «Інконтиненталь» потребують доброго прибирання!",
    ["The supply wagon will depart shortly. Prepare to escort it to its destination."] = "Воз із припасами скоро вирушить. Приготуйся супроводити його до місця призначення.",
    ["The swamp stinks of malevolence and anguish."] = "Болото смердить злобою й мукою.",
    ["The sword and shield are yours, claim them."] = "Меч і щит твої — забери їх.",
    ["The theater performance starts soon!"] = "Театральна вистава скоро почнеться!",
    ["The time has come for you and Durotan to confront Warlord Garrosh Hellscream."] = "Настав час тобі й Дуротану стати проти Воєначальника Ґарроша Хеллскріма.",
    ["The time has come for you and Vindicator Yrel to confront Warlord Garrosh Hellscream."] = "Настав час тобі й Захисниці Йрел стати проти Воєначальника Ґарроша Хеллскріма.",
    ["The time has come to assault Queen Azshara in her seat of power."] = "Настав час напасти на Королеву Азшару в осередку її могутності.",
    ["The timer should start here."] = "Тут має запуститися таймер.",
    ["The trial is about to begin."] = "Випробування ось-ось почнеться.",
    ["The trial is over. Take up the Truthguard."] = "Випробування завершено. Візьми Правдощит.",
    ["The venom of Ula'tek has transformed its inhabitants into brutish monstrosities."] = "Отрута Ула'тек перетворила тутешніх мешканців на дикунських потвор.",
    ["The village is shrouded in mists. Light the bonfire to clear it and provoke the Helarjar."] = "Селище огорнуте туманом. Запали багаття, щоб розвіяти його й розворушити геларярів.",
    ["The visions have overwhelmed the defenses. Reactivate the sentries and defeat any adversaries in order to proceed."] = "Видіння здолали захист. Знову активуй вартових і подолай усіх ворогів, щоб рушити далі.",
    ["The wards are activated, it is time to begin the ritual. Go to the Altar of End Times and speak with Meryl Felstorm."] = "Обереги активовано, час починати ритуал. Іди до Вівтаря Кінця Часів і поговори з Меріл Фелсторм.",
    ["The way below is uncovered, make your way to the prison of Zakajz."] = "Шлях униз відкрито, пробивайся до в'язниці Закаджза.",
    ["The way forward is blocked with waxy buildup. Defeat Waximus to dislodge it."] = "Шлях уперед перекритий восковими наростами. Подолай Ваксімуса, щоб усунути їх.",
    ["The way is clear to the Nighthold. Secure the entrance."] = "Шлях до Нічної Твердині вільний. Закріпись біля входу.",
    ["The way is open and the shrine awaits. The shield is below somewhere. Find it."] = "Шлях відкрито, і святилище чекає. Щит десь унизу. Знайди його.",
    ["The way is open into the complex. Continue down into the structure and locate Margrave."] = "Шлях до комплексу відкрито. Спускайся вглиб споруди й відшукай Марграва.",
    ["The way is open to the prison. Continue down the unsealed passage to whatever waits below."] = "Шлях до в'язниці відкрито. Спускайся розпечатаним проходом до того, що чекає внизу.",
    ["The wrath of the Eagle has grounded the Hive Seer!"] = "Лють Орла приземлила Провидця Вулика!",
    ["Their Blood Will Flow"] = "Їхня кров проллється",
    ["Theotar likes a Formal court, so offer him some tea."] = "Теотар полюбляє світські манери, тож запропонуй йому чаю.",
    ["Theramore's Fall"] = "Падіння Терамору",
    ["There is a lot of moose! Get rid of 'em!"] = "Тут повно лосів! Розберися з ними!",
    ["There's More"] = "Це ще не все",
    ["There's a Leper Rat of unusual size guarding that door. It looks mean."] = "Ті двері стереже Прокажений Пацюк незвичних розмірів. Вигляд у нього лютий.",
    ["There's a New Master in Town"] = "У місті новий господар",
    ["There's a crisis in the Vatworks! A fashion crisis!"] = "У Чанокузні криза! Криза моди!",
    ["There's a monster in Lil' Bitsy's house! Help!!!"] = "У домі Малятка Бітсі завелося чудовисько! Допоможіть!!!",
    ["Thermaplugg's End"] = "Кінець Термаплага",
    ["These caverns were once home to fierce creatures, locked in a cycle of predation that ultimately led to their own extinction."] = "Колись ці печери були домівкою лютих створінь, замкнених у колі хижацтва, що зрештою привело їх до власного вимирання.",
    ["These pets have found their forever homes! Pick them up from their foster."] = "Ці улюбленці знайшли свої постійні домівки! Забери їх у опікуна.",
    ["They Are Not Prepared"] = "Вони не готові",
    ["They Have a New Plan"] = "У них новий план",
    ["They Spent Years on That?"] = "Вони витратили на це роки?",
    ["Think of the Children"] = "Подумай про дітей",
    ["Thirsty Menace"] = "Спрагла загроза",
    ["Thirsty Rampage"] = "Спрагле буйство",
    ["This Ship Will Self-Destruct in..."] = "Цей корабель самознищиться за...",
    ["This aspiring author can't write until he finds the perfect name!"] = "Цей письменник-початківець не може писати, доки не знайде ідеальне ім'я!",
    ["This is a good place to hide. Safe. Secure. Away from everyone. Everything."] = "Це гарне місце, щоб сховатися. Безпечне. Захищене. Подалі від усіх. Від усього.",
    ["This is a scenario description"] = "Це опис сценарію",
    ["This is the final step! (cm 109970)"] = "Це останній крок! (cm 109970)",
    ["This scrap sculptor needs help finding scrap with artistic potential!"] = "Цьому скульпторові з брухту потрібна допомога — знайти брухт із мистецьким потенціалом!",
    ["Thisalee has a lead! Go see what she found."] = "У Тисалі є зачіпка! Іди подивися, що вона знайшла.",
    ["Thoradin's Folly"] = "Безум Торадіна",
    ["Thorim, Lord of Thunder"] = "Торім, Володар Грому",
    ["Thorn in Our Side"] = "Скалка в боці",
    ["Thousandbite Piranha Collar can be purchased from Junnik, located near the tents south of the pot."] = "Нашийник Тисячозубої Піраньї можна купити в Джунніка, що стоїть біля наметів на південь від казана.",
    ["Threadmaestro's Blockade"] = "Блокада Ниткомаестро",
    ["Threat from the West"] = "Загроза із заходу",
    ["Threat!"] = "Загроза!",
    ["Threats Above"] = "Загроза згори",
    ["Thrice-Charred Mammoth Ribs can be purchased from Qariin Dotur, who patrols the path south of the pot."] = "Тричі обвуглені реберця мамонта можна купити в Каріін Дотур, що патрулює стежку на південь від казана.",
    ["Through corruptive magic and draining old allies, Faithbreaker Ger'lok is paving a new path for him and the Twilight's Blade he leads."] = "Магією зіпсуття й висотуванням колишніх союзників Зрадник Віри Ґер'лок прокладає новий шлях для себе й Клинка Сутінків, який він очолює.",
    ["Throw flowers at the earthen couple."] = "Кидай квіти в земляну пару.",
    ["Throw it into the pot!"] = "Кинь це в казан!",
    ["Throw souvenir goblets to the audience."] = "Кидай сувенірні келихи глядачам.",
    ["Throw souvenir tapestries to the audience."] = "Кидай сувенірні гобелени глядачам.",
    ["Throw the \"Volcano\" Duck into the pot!"] = "Кинь «Вулканічну» Качку в казан!",
    ["Throw the Dragonflame Argali into the pot!"] = "Кинь Драконвогняного Аргалі в казан!",
    ["Throw the Dried Coldsnap Sagittate into the pot!"] = "Кинь Сушений Морозний Стрілолист у казан!",
    ["Throw the Exquisite Ohn'ahran Potato into the pot!"] = "Кинь Вишукану Он'агранську Картоплю в казан!",
    ["Throw the Eye of Bass into the pot!"] = "Кинь Око Окуня в казан!",
    ["Throw the Flaky Pastry Dough into the pot!"] = "Кинь Листкове Тісто в казан!",
    ["Throw the Fresh Dragon Fruit into the pot!"] = "Кинь Свіжий Драконфрукт у казан!",
    ["Throw the Frightened Baby Murlocs back to their own dimension."] = "Поверни наляканих мурлочків-малюків у їхній власний вимір.",
    ["Throw the Greenberry into the pot!"] = "Кинь Зеленоягоду в казан!",
    ["Throw the Island Crab Jerky into the pot!"] = "Кинь В'ялене М'ясо Острівного Краба в казан!",
    ["Throw the Juicy Bushfruit into the pot!"] = "Кинь Соковитий Кущоплід у казан!",
    ["Throw the Lunker Bits into the pot!"] = "Кинь Шматочки Здоровила в казан!",
    ["Throw the Rations: Scorpid Surprise into the pot!"] = "Кинь Пайок: Скорпідний Сюрприз у казан!",
    ["Throw the Salted Fish Scraps into the pot!"] = "Кинь Солоні Рибні Обрізки в казан!",
    ["Throw the Seven Spices Bruffalon into the pot!"] = "Кинь Бруффалона на Сімох Спеціях у казан!",
    ["Throw the Thousandbite Piranha Collar into the pot!"] = "Кинь Нашийник Тисячозубої Піраньї в казан!",
    ["Throw the Thrice-Charred Mammoth Ribs into the pot!"] = "Кинь Тричі обвуглені реберця мамонта в казан!",
    ["Throw them into the pot!"] = "Кинь їх у казан!",
    ["Throw wind and water around the stage."] = "Здіймай вітер і воду навколо сцени.",
    ["Throw wood at Wanderer Ida's ship."] = "Кидай дерево в корабель Мандрівниці Іди.",
    ["Thunder and Crash"] = "Грім і гуркіт",
    ["Thunder in Frostfire"] = "Грім у Льодополум'ї",
    ["Thunder of the Titans"] = "Грім Титанів",
    ["Thunderlord clan members of the Iron Horde have enslaved the mighty gronn, Durn the Hungerer. Slay him."] = "Члени клану Громовладців із Залізної Орди поневолили могутнього гронна, Дурна Голодного. Убий його.",
    ["Thwart Neltharion's plot to unleash darkness."] = "Зірви задум Нелтаріона вивільнити темряву.",
    ["Thystoria"] = "Тісторія",
    ["Ticket Distribution"] = "Роздача квитків",
    ["Tide and Seek"] = "Приплив і пошук",
    ["Tides of Glory"] = "Припливи Слави",
    ["Time Rift!"] = "Розлом Часу!",
    ["Time to Clean: Suds the Janitor"] = "Час прибирати: прибиральник Садс",
    ["Time to go."] = "Час іти.",
    ["Timer Over"] = "Час вийшов",
    ["Timeway: A.Z.E.R.O.T.H."] = "Часоплин: A.Z.E.R.O.T.H.",
    ["Timeway: Azewrath"] = "Часоплин: Азеврат",
    ["Timeway: Azmerloth"] = "Часоплин: Азмерлот",
    ["Timeway: Azmourne"] = "Часоплин: Азморн",
    ["Timeway: Azq'roth"] = "Часоплин: Азк'рот",
    ["Timeway: The Warlands"] = "Часоплин: Воєнні Землі",
    ["Timeway: Ulderoth"] = "Часоплин: Улдерот",
    ["Timmy the Cruel defeated"] = "Тіммі Жорстокого подолано",
    ["Tiny In Size, Brimming With Evil"] = "Малий на зріст, повний зла",
    ["Tire the Boar Out"] = "Утоми вепра",
    ["To Balance Nature"] = "Урівноважити природу",
    ["To Catch a Cultist"] = "Спіймати культиста",
    ["To Dam the Damned"] = "Загатити проклятих",
    ["To Fight Another Day"] = "Битися ще один день",
    ["To Kill a C'Thraxxi"] = "Убити к'тракссі",
    ["To Protect and Heal"] = "Захищати й зцілювати",
    ["To Smithereens!"] = "На друзки!",
    ["To The Skies"] = "У небеса",
    ["To Wield the Flame"] = "Володіти полум'ям",
    ["To cleanse the Nightmare, the brave must ascend the great tree Shaladrassil, where the veil of dreams is thinnest."] = "Щоб очистити Жахіття, відважні мусять зійти на велике дерево Шаладрассіл, де завіса снів найтонша.",
