    ["Towering Pillars"] = "Височенні стовпи",
    ["Track Lixahl's blood until you find it. You can use your Spectral Sight to assist with the tracking."] = "Іди по сліду крові Ліксала, доки не знайдеш його. Можеш скористатися Примарним Зором, щоб полегшити пошук.",
    ["Track down Exarch Orelis in Evermorn Hold."] = "Вистеж Екзарха Ореліса у Твердині Еверморн.",
    ["Track down Nathanos Blightcaller."] = "Вистеж Натаноса Блайткаллера.",
