    ["Traitors in Our Midst"] = "Зрадники серед нас",
    ["Travard must complete the ritual to unlock the hammer from the wards. Defend the crypt until he is finished!"] = "Травард мусить завершити ритуал, щоб звільнити молот з-під оберегів. Захищай склеп, доки він не закінчить!",
    ["Travard wants to begin the ritual. Aid him."] = "Травард хоче почати ритуал. Допоможи йому.",
    ["Travard's team is set up in the abandoned Twilight camp. Meet up with him."] = "Загін Траварда отаборився в покинутому таборі Сутінків. Зустрінься з ним.",
    ["Travel deep into the Big Blossom Mine and blast open the wall."] = "Заглибся в Шахту Великого Цвіту й висади стіну.",
    ["Travel to Beastwatch"] = "Вирушай до Біствоча",
    ["Travel to the Broken Shore."] = "Вирушай до Зламаного Берега.",
    ["Travel to the Broken Shore. (A)"] = "Вирушай до Зламаного Берега. (A)",
    ["Travel to the Broken Shore. (H)"] = "Вирушай до Зламаного Берега. (H)",
    ["Travel to the Frozen Throne"] = "Вирушай до Крижаного Трону",
    ["Travel to the Masons' Quarter and awaken the unconscious villagers."] = "Вирушай до Кварталу Каменярів і розбуди непритомних селян.",
    ["Travel to the citadel and assist Baron Sliver as he disables its barrier."] = "Вирушай до цитаделі й допоможи Барону Сліверу вимкнути її бар'єр.",
    ["Travel to the core of Manaforge Omega and come face-to-face with darkness incarnate: Dimensius, the All-Devouring."] = "Вирушай до ядра Манакузні Омеґа й стань віч-на-віч із втіленням темряви — Дименсіусом Всепожиральним.",
    ["Traverse into De Other Side to aid Bwonsamdi against the primal loa Mueh'zala."] = "Пройди до Іншого Боку, щоб допомогти Бвонсамді проти первісного лоа Муех'зали.",
    ["Traverse into De Other Side to slay Hakkar."] = "Пройди до Іншого Боку, щоб убити Гаккара.",
    ["Treasure"] = "Скарб",
    ["Trial By Holy Fire"] = "Випробування Святим Вогнем",
    ["Trial of Storms"] = "Випробування Бур",
