    ["Try once more to claim Deathwing's essence."] = "Спробуй ще раз заволодіти есенцією Дезвінга.",
    ["Try to fish Gary the Goldfish out of the sewers."] = "Спробуй виловити Ґері Золоту Рибку зі стічних труб.",
    ["Tugar has gone to ground in the Cave of the Bloodtotem. It's time to put an end to him."] = "Туґар заліг на дно в Печері Кривавого Тотема. Час покласти йому край.",
