    ["Two Heads Are Better"] = "Дві Голови Краще",
    ["Two of Caria's lieutenants are performing a dark ritual. They must be stopped."] = "Двоє поплічників Карії проводять темний ритуал. Їх треба зупинити.",
    ["Typhinius has summoned his servants, survive the assault!"] = "Тифініус прикликав своїх слуг — виживи в навалі!",
    ["Tyr's Last Stand"] = "Останній бій Тіра",
    ["Tyr's crypt is overrun with crazed aberrations. Clear them out to begin the ritual."] = "Склеп Тіра захопили очманілі аберації. Очисти його, щоб почати ритуал.",
    ["Tyrande Whisperwind's Refusal"] = "Відмова Тіранди Шепіт Вітру",
    ["Tyrande charged ahead. Deal with the incoming Maw minions!"] = "Тіранда кинулася вперед. Розберися з поплічниками Пащі, що насуваються!",
    ["Tyrande has pushed forward. Find another way to catch up with her."] = "Тіранда прорвалася вперед. Знайди інший спосіб наздогнати її.",
    ["Tyrande is gone, but you can still save the group of night elves trapped in the Maw."] = "Тіранда зникла, але ти ще можеш урятувати гурт нічних ельфів, ув'язнених у Пащі.",
    ["Tyrande is not stopping. Try to keep up with her."] = "Тіранда не зупиняється. Намагайся не відставати від неї.",
    ["Tyrande is up ahead, try to catch up with her!"] = "Тіранда попереду — намагайся наздогнати її!",
    ["Tyrande must be up ahead. Find her!"] = "Тіранда, певно, попереду. Знайди її!",
    ["Tyrande's Ascension"] = "Піднесення Тіранди",
    ["Tyranis Malem was sent ahead deeper into D-Block. Head into the cells, find him, and find out what he knows."] = "Тіраніса Малема відправили вперед, углиб блоку D. Зайди до камер, знайди його й дізнайся, що йому відомо.",
    ["Uldaman: Legacy of Tyr"] = "Улдаман: Спадок Тіра",
