    ["Unstable void energies are gathering, follow Travard back up to the crypt before the area is consumed."] = "Збираються нестабільні енергії Порожнечі. Іди за Травардом назад до крипти, поки місцину не поглинуло.",
    ["Untangle the roots as Ruilla did, bending them to her will and drawing upon the power of Harandar."] = "Розплутай коріння, як це зробила Руілла, підкоривши його своїй волі та черпаючи силу Гарандара.",
    ["Until Next Time"] = "До наступної зустрічі",
