    ["Untimely Intruder"] = "Несвоєчасний зайда",
    ["Unwelcome Reminder"] = "Небажане нагадування",
    ["Unwind and enjoy the leftovers. Stay as long as you like!"] = "Відпочинь і скуштуй те, що лишилося. Залишайся, скільки забажаєш!",
    ["Up and Away"] = "Вгору і геть",
