    ["Upper Passage Hunt"] = "Полювання у Верхньому проході",
    ["Upper Return to Karazhan"] = "Повернення до Каражану: Верхні Поверхи",
    ["Urok Doomhowl defeated"] = "Урок Думгоул переможений",
    ["Urso Wooster has procured a very special package and needs someone to deliver it."] = "Урсо Вустер роздобув дуже особливу посилку, і йому потрібен хтось, хто її доставить.",
    ["Urso Wooster: Bear Care"] = "Урсо Вустер: Ведмежий догляд",
    ["Ursoc's Lair"] = "Лігво Урсока",
    ["Use Bwonsamdi's Death Gate to escape the Frozen Throne."] = "Скористайся Брамою Смерті Бвонсамді, щоб утекти з Крижаного Трону.",
    ["Use Hap'he to catch Juicy Clues around the site!"] = "Скористайся Гап'ге, щоб ловити Соковиті Підказки по всій місцині!",
    ["Use Hap'he to collect clues around the site!"] = "Скористайся Гап'ге, щоб збирати підказки по всій місцині!",
    ["Use Lasan's War Eagles to reach the Legion Ship."] = "Скористайся бойовими орлами Ласана, щоб дістатися корабля Легіону.",
    ["Use Niya's traps to defend the North Gate."] = "Скористайся пастками Нії, щоб захистити Північну браму.",
    ["Use Torra's spear to bring down the felbat Falthus."] = "Скористайся списом Торри, щоб збити скверножера Фалтуса.",
    ["Use Withered to Drain Andaris's shield."] = "Скористайся Висхлими, щоб виснажити щит Андаріса.",
    ["Use a charged battery to destroy the Azerite Collectors!"] = "Скористайся зарядженою батареєю, щоб знищити Збирачів азериту!",
    ["Use an arcane portal to travel to the center Band of Transmutation"] = "Скористайся арканним порталом, щоб дістатися центрального Кільця Трансмутації",
    ["Use blight on Alliance forces to drive them away."] = "Застосуй пошесть проти сил Альянсу, щоб їх відігнати.",
    ["Use bombs to close Sureki burrows."] = "Скористайся бомбами, щоб закрити нори суреків.",
    ["Use ingredients in the Brightwing Estate laboratory to brew a cure!"] = "Скористайся інгредієнтами в лабораторії маєтку Брайтвінг, щоб зварити ліки!",
    ["Use magnets to shove the Field Despair Bot into the electrical pylon!"] = "Скористайся магнітами, щоб заштовхати Польового Бота Відчаю в електричний пілон!",
    ["Use rocks to clear all the Horned Filcher Nests from the trees."] = "Скористайся камінням, щоб прибрати з дерев усі Гнізда Рогатих Злодюжок.",
    ["Use the Cleansing Cure to purge the Void from the animals of the Brightwing Estate Menagerie."] = "Скористайся Очисними Ліками, щоб вигнати Порожнечу зі звірів звіринцю маєтку Брайтвінг.",
    ["Use the Deck Guns to shoot down Forsaken Dreadwings"] = "Скористайся палубними гарматами, щоб збити Жахокрилів Відступників",
    ["Use the Doomhammer to destroy Geth'xun."] = "Скористайся Молотом Згуби, щоб знищити Гет'ксуна.",
    ["Use the Fel Cannons to clear the airspace around the tower."] = "Скористайся гарматами Скверни, щоб очистити повітряний простір довкола вежі.",
    ["Use the Gatekeeper's Orb to open the gate to the Bloodied Crossing."] = "Скористайся Сферою Воротаря, щоб відчинити браму до Скривавленого Перехрестя.",
    ["Use the Portal to meet with Sylvanas Windrunner."] = "Скористайся Порталом, щоб зустрітися із Сильваною Віндраннер.",
    ["Use the Ritual Focus whenever possible to complete the ritual."] = "Користуйся Ритуальним Осердям щоразу, коли це можливо, щоб завершити ритуал.",
    ["Use the Shrines of Earth and Sky"] = "Скористайся Святилищами Землі та Неба",
    ["Use the Storm Drakes to extract."] = "Скористайся Штормовими дрейками, щоб евакуюватися.",
    ["Use the animacone to transform Glittermint into the Winter Queen."] = "Скористайся анімаконусом, щоб перетворити Блиском'яту на Зимову Королеву.",
    ["Use the artifact to eliminate your enemies."] = "Скористайся артефактом, щоб знищити своїх ворогів.",
    ["Use the correct sequence of levers to activate the Door Control Console."] = "Скористайся правильною послідовністю важелів, щоб увімкнути Пульт Керування Дверима.",
    ["Use the drakes to escape the Legion ship before it is destroyed."] = "Скористайся дрейками, щоб утекти з корабля Легіону, перш ніж його знищать.",
    ["Use the eagles to get off the ship."] = "Скористайся орлами, щоб залишити корабель.",
    ["Use the forged glove to claim the last of Deathwing's Black Dragon essence"] = "Скористайся викуваною рукавицею, щоб забрати останки чорнодраконячої есенції Дезвінга",
    ["Use the lift in The Maker's Rise to locate the anomaly."] = "Скористайся підіймачем у Височині Творця, щоб виявити аномалію.",
    ["Use the power granted by the Forge of the Guardian to defeat Kathra'natir."] = "Скористайся силою, дарованою Кузнею Вартового, щоб перемогти Катра'натіра.",
    ["Use the props on the stage to prove your might!"] = "Скористайся реквізитом на сцені, щоб довести свою міць!",
    ["Use the smoke bomb to create a distraction in the Trader's Hall."] = "Скористайся димовою бомбою, щоб влаштувати відвертання уваги в Залі торговців.",
    ["Use the storm drakes to eliminate the Legion's ground forces."] = "Скористайся штормовими дрейками, щоб знищити наземні сили Легіону.",
    ["Use the turret at the top of Beastwatch Tower to defend the Mag'har."] = "Скористайся турелькою на вершині Вежі Звіриної Варти, щоб захистити маг'харів.",
    ["Use the unholy essence to raise your dragon."] = "Скористайся нечестивою есенцією, щоб підняти свого дракона.",
    ["Use the void portal."] = "Скористайся порталом Порожнечі.",
    ["Use torches to destroy Corrupted Sureki Eggs."] = "Скористайся смолоскипами, щоб знищити Зіпсовані яйця суреків.",
    ["Use what you have learned to defeat a solo opponent."] = "Застосуй здобуті знання, щоб перемогти одного суперника.",
    ["Use what you have learned to defeat two opponents at the same time."] = "Застосуй здобуті знання, щоб перемогти двох суперників одночасно.",
    ["Use your Flare to see if Hakkar has taken the bait."] = "Скористайся своєю Сигнальною ракетою, щоб побачити, чи Гаккар клюнув на наживку.",
    ["Use your demonic senses to pickup Caria's trail."] = "Скористайся своїми демонічними чуттями, щоб узяти слід Карії.",
    ["Use your otter familiar to defeat and collect information-stuffed clues!"] = "Скористайся своєю видрою-фамільяром, щоб перемагати ворогів і збирати підказки, напхані відомостями!",
    ["Use your senses to search for clues."] = "Скористайся своїми чуттями, щоб шукати підказки.",
    ["Using the void magic stolen from the captured void creatures, Lady Selen'vjar is empowering a Mindbreaker from the deep."] = "Викравши магію Порожнечі в полонених створінь Порожнечі, леді Селен'в'яр посилює Розумоламача з глибин.",
    ["Utilize the Shrines to collect Impurity Orbs."] = "Скористайся Святилищами, щоб зібрати Сфери Скверни.",
    ["Vanguard of the Assault"] = "Авангард штурму",
    ["Vase Props"] = "Реквізитні вази",
    ["Vashnik the Malignant combines various elements with the venom of Ula'tek to create a toxin so potent it brings Azeroth to its knees."] = "Вашник Лиховісний поєднує різні стихії з отрутою Ула'тек, щоб створити токсин, такий потужний, що ставить Азерот на коліна.",
    ["Vatworks Needs a Makeover: Glamma Enchanto"] = "Чановарні потрібне оновлення: Ґламма Енчанто",
    ["Vengeance for the Illidari"] = "Помста за Іллідарі",
    ["Venom Lancer Ori'Kassi Rises"] = "Отруйна Списниця Орі'Кассі повстає",
    ["Venomfall Deeps"] = "Глибини Отрутопаду",
    ["Venture No Further"] = "Далі не йди",
    ["Venture deeper into Sporefall and defeat Rotmire."] = "Заглибся в Спорепад і перемож Гнилобагно.",
    ["Verlann Timbercrush marches on the World Tree to burn Sprucecrown down. Defeat her!"] = "Верланн Тимберкраш іде на Світове Дерево, щоб спалити Ялинокрону. Перемож її!",
    ["Vermillion Holdout"] = "Багряний редут",
    ["Verstok has fled into a series of caves beneath the ruins, find him."] = "Версток утік до низки печер під руїнами. Знайди його.",
    ["Verstok's scent leads into the ruins, but the door is sealed shut. Find a way to open it."] = "Слід Верстока веде до руїн, але двері запечатано. Знайди спосіб їх відчинити.",
    ["Very Important Earthen"] = "Дуже важливий земнокровний",
