    ["Vigfus and his souls are below, kill the mystics defending the path down and reach the docks."] = "Віґфус і його душі внизу. Убий містиків, що боронять шлях донизу, і дістанься доків.",
    ["Vigfus continues to ignore your presence. Free his cargo of souls to draw him out."] = "Віґфус і далі ігнорує твою присутність. Звільни його вантаж душ, щоб виманити його.",
