    ["Void Ritual: Grizzly"] = "Ритуал Порожнечі: Ґризлі",
    ["Void energy has concentrated into one Gnarldin champion, who must be defeated to free them from the Void."] = "Енергія Порожнечі зосередилася в одному чемпіоні корчедінів, якого треба перемогти, щоб звільнити їх від Порожнечі.",
    ["Void obelisks are corrupting a creature they intend to unleash on the people of this land."] = "Обеліски Порожнечі псують створіння, яке вони мають намір нацькувати на мешканців цього краю.",
    ["Void reinforcements are spawning from portals..."] = "З порталів з'являється підкріплення Порожнечі...",
