    ["Wait for Chromie's preparations to finish."] = "Зачекай, поки Хромі завершить приготування.",
    ["Wait for the portal to open."] = "Зачекай, поки відкриється портал.",
    ["Wait for the tournament to begin."] = "Зачекай початку турніру.",
    ["Wait to begin the counter attack."] = "Зачекай, перш ніж розпочати контратаку.",
    ["Waiting Room (Step 2)"] = "Кімната очікування (Крок 2)",
    ["Waiting to Begin"] = "Очікування початку",
    ["Wake Tess"] = "Розбуди Тесс",
    ["Wake the Woodcutters"] = "Розбуди лісорубів",
    ["Waken and hunt Khuumog."] = "Прокинься й вистеж Кгуумоґа.",
    ["Walk To Area 3"] = "Іди до Зони 3",
    ["Walk with Akama to the Shrine of Lost Souls."] = "Іди з Акамою до Святилища Загублених Душ.",
    ["Walk with Cairne and Baine."] = "Іди з Кайрном і Байном.",
    ["Walk with Magni Bronzebeard to the Celestial Planetarium."] = "Іди з Маґні Бронзобородом до Небесного Планетарію.",
    ["Walk with Temel to the refreshments area."] = "Іди з Темелем до зони частувань.",
    ["Walk with Umbric and Alleria."] = "Іди з Умбриком та Аллерією.",
    ["Warbringer Qobi"] = "Войовниця Кобі",
    ["Warchief Sylvanas has need of this prisoner."] = "Вождю Сильвані потрібен цей бранець.",
    ["Warden Amical and his soldiers are the last obstruction. Once they are defeated, the path to freedom is clear."] = "Наглядач Амікаль та його солдати — остання перешкода. Щойно їх буде переможено, шлях до свободи відкриється.",
    ["Warlord Gurrtack is leading the Twilight's Blade forces behind this Ritual Site."] = "Воєначальник Ґурртак очолює сили Клинка Сутінків за цим Ритуальним Місцем.",
    ["Warlord Volund seeks to stop you from claiming Titanstrike."] = "Воєначальник Волунд прагне завадити тобі здобути Титаноудар.",
    ["Warmage Bernante"] = "Бойовий маг Бернанте",
    ["Warped Gates"] = "Викривлені брами",
    ["Waste the Great Glorious Alliance's store of cannonballs."] = "Знищ запас гарматних ядер Великого Славного Альянсу.",
    ["Watch Infazzar and determine his plans"] = "Поспостерігай за Інфаззаром і дізнайся його плани",
    ["Watch as Ruilla the Huntress accepts the Root of the World and the guardianship it entails to become the first Rootwarden of Harandar."] = "Подивися, як мисливиця Руілла приймає Корінь Світу та опіку, яку він на неї покладає, щоб стати першим вартовим коренів Гарандара.",
    ["Watch over Archmage Khadgar as he channels his essence into the arcane vessel."] = "Наглядай за архімагом Хадґаром, поки він спрямовує свою есенцію в арканну посудину.",
    ["Watcher Zalesx"] = "Спостерігач Залескс",
    ["Watchmaster Boromod likes a Casual court. Start a fight to entertain him."] = "Наглядач Боромод полюбляє невимушений двір. Розпочни бійку, щоб його розважити.",
    ["Water Gauntlet"] = "Водяна рукавиця",
    ["Wave 1"] = "Хвиля 1",
    ["Wave 2"] = "Хвиля 2",
