    ["Waycrest Manor"] = "Маєток Вейкрестів",
    ["We Glorious Few"] = "Ми, славні небагато",
    ["We Need Answers"] = "Нам потрібні відповіді",
    ["We should check the bulletin board before we head out for the day."] = "Варто перевірити дошку оголошень, перш ніж вирушати на цілий день.",
    ["We're busting the crabs out of the supermarket! Long live the crabs!"] = "Ми визволяємо крабів із супермаркету! Хай живуть краби!",
    ["We're on a roll! Stand close to Eadweard and await instructions. Can you dig it?"] = "Нам щастить! Стань ближче до Едварда й чекай вказівок. Уловлюєш?",
    ["We've won this fight. Listen to what Zul'jarra has to say."] = "Ми виграли цей бій. Послухай, що скаже Зул'джарра.",
    ["Weaken the storm by defeating elementals."] = "Послаб бурю, перемагаючи елементалів.",
