    ["Wetwork"] = "Мокра справа",
    ["Wey'nan has vowed to track down the creature \"Zarat\" that attacked his people."] = "Вей'нан поклявся вистежити створіння «Зарат», що напало на його народ.",
    ["Wey'nan has won in his battle with Zarat, but he also has been gripped by an all-consuming fury. The scents of the mushrooms in the cavern will help him calm down."] = "Вей'нан переміг у битві із Заратом, але його охопила нестримна лють. Запахи грибів у печері допоможуть йому заспокоїтися.",
    ["Wey'nan regrets the primal rage that overtook him. He wants your help in creating a memento to remind the haranir not to give in to their rage."] = "Вей'нан шкодує про первісну лють, що його охопила. Він хоче, щоб ти допоміг створити пам'ятку, яка нагадуватиме гаранірам не піддаватися своїй люті.",
    ["Wey'nan wants to create a memento of the battle--a reminder that succumbing to rage is a terrible thing."] = "Вей'нан хоче створити пам'ятку про битву — нагадування про те, що піддаватися люті — жахлива річ.",
    ["What Evil Comes"] = "Яке лихо насувається",
    ["What Is All This Junk?"] = "Що це за мотлох?",
    ["What Lies Ahead"] = "Що чекає попереду",
    ["What Troubles from Above?"] = "Яка біда згори?",
    ["What's Beneath the Surface"] = "Що під поверхнею",
    ["What's Cooking"] = "Що там вариться",
    ["What's In A Name?"] = "Що в імені тобі моїм?",
    ["What's Yours is Mine!"] = "Що твоє, те моє!",
    ["What's below?"] = "Що там унизу?",
    ["What's the Verdict?"] = "Який вирок?",
    ["When One Dagger Just Isn't Enough"] = "Коли одного кинджала просто замало",
    ["When One Door Closes..."] = "Коли зачиняються одні двері...",
    ["When Sargeras plunged his sword into Azeroth, it tainted the very lifeblood of the world, unleashing monstrosities whose echoes still resonate to this day."] = "Коли Саргерас увігнав свій меч в Азерот, він осквернив саму кров світу, вивільнивши потвор, чиї відлуння лунають донині.",
    ["When You're Finished Exploring, End Day 1"] = "Коли завершиш дослідження, закінчи День 1",
    ["When You're Finished Exploring, End Day 11"] = "Коли завершиш дослідження, закінчи День 11",
    ["When You're Finished Exploring, End Day 4"] = "Коли завершиш дослідження, закінчи День 4",
    ["When You're Finished Exploring, End Day 6"] = "Коли завершиш дослідження, закінчи День 6",
    ["When the Forest Walks"] = "Коли Ліс Іде",
    ["When the Nerubian Queen dared to renounce the Old Gods, the battle that ensued was violent and gruesome."] = "Коли Неруб'янська Королева наважилася зректися Прадавніх Богів, битва, що зчинилася, була жорстокою та кривавою.",
    ["When you're ready to leave, speak with Grayson and he'll see you returned to Light's Hope Chapel."] = "Коли будеш готовий вирушати, поговори з Ґрейсоном, і він поверне тебе до Каплиці Надії Світла.",
    ["Where Are They?"] = "Де вони?",
    ["Where Is She?"] = "Де вона?",
    ["Where There's a Withered There's a Way"] = "Де є Висхлий, там є і шлях",
    ["Where is Meerah?"] = "Де Міра?",
    ["Where is the Air Support?"] = "Де повітряна підтримка?",
    ["Where is the Echoless Flame?"] = "Де Безвідлунне Полум'я?",
    ["Where the Pieces Fall"] = "Куди впадуть фрагменти",
    ["Where the Silence Answered"] = "Де Відповіла Тиша",
    ["While We're Down"] = "Поки Ми Внизу",
    ["While escorting the supply wagon, destroy the first barricade and defeat Teposutl."] = "Супроводжуючи воза з припасами, знищ першу барикаду й перемож Тепосутля.",
    ["While escorting the supply wagon, destroy the second barricade and defeat Chiui."] = "Супроводжуючи воза з припасами, знищ другу барикаду й перемож Чіуї.",
    ["While escorting the supply wagon, destroy the third barricade and defeat Siul."] = "Супроводжуючи воза з припасами, знищ третю барикаду й перемож Сіуля.",
    ["Whoa there is a big dude now, kill 'em!"] = "Ого, тепер тут здоровань — убий його!",
    ["Wicked Woodpeckers"] = "Лихі дятли",
    ["Wield G'Hanir, the Mother Tree."] = "Володій Ґ'Ганіром, Деревом-Матір'ю.",
    ["Wield Thas'dorah, Legacy of the Windrunners."] = "Володій Тас'дорою, Спадком Віндраннерів.",
    ["Wield the Fangs of the Devourer."] = "Володій Іклами Пожирача.",
    ["Wield the Twinblades of the Deceiver."] = "Володій Парноклинками Дурисвіта.",
    ["Will No One Help?"] = "Невже ніхто не допоможе?",
    ["Willey Hopebreaker defeated"] = "Віллі Гоупбрейкер переможений",
    ["Win favor with the powerful cartels of Tazavesh and locate So'leah!"] = "Здобудь прихильність могутніх картелів Тазавеша й вистеж Со'лею!",
    ["Wisped Away"] = "Розвіяний серпанком",
    ["With Fu Zan in hand, ride upon Yu'lon to return to the Wandering Isle."] = "З Фу Заном у руках осідлай Ю'лон, щоб повернутися на Острів Мандрів.",
    ["With Gorelix dead his axe is now yours. Take it."] = "Ґорелікс мертвий — його сокира тепер твоя. Візьми її.",
    ["With Jorvinax dead the portal is left unguarded. Find a way to destroy it!"] = "Джорвінакс мертвий — портал лишився без охорони. Знайди спосіб знищити його!",
    ["With Lady Calindris dead the staff is now yours. Take it and leave Niskara."] = "Леді Каліндріс мертва — посох тепер твій. Візьми його й покинь Ніскару.",
    ["With People to Feed"] = "Стільки ротів годувати",
    ["With Time to Spare"] = "Часу вдосталь",
    ["With a seance on the books and the ghosts a no-show, Hoaxarella needs a little mortal help."] = "Сеанс призначено, а привиди не з'явилися, тож Гоаксарелла потребує невеликої смертної допомоги.",
    ["With his control slipping, Chrome King Gallywix prepares to destroy Undermine."] = "Втрачаючи контроль, Хромований Король Ґаллівікс готується знищити Андермайн.",
    ["With the Deacon dead, the Blade is now yours. Take it."] = "Дякон мертвий — Клинок тепер твій. Візьми його.",
    ["With the keystone in hand release your ally."] = "Тримаючи ключ у руці, звільни свого союзника.",
    ["Withstand the fury of Sindragosa!"] = "Витримай лють Синдрагоси!",
    ["Witness Chromie's demise."] = "Стань свідком загибелі Хромі.",
    ["Witness Chromie's demise... again."] = "Стань свідком загибелі Хромі... знову.",
    ["Witness Commander Vorka's arrival."] = "Стань свідком прибуття командира Ворки.",
    ["Witness Sai'alyo as she teaches a pupil the secrets of the pigments and the sacred ritual of hand-signature, forming the first of the Zur'ashar."] = "Спостерігай, як Сай'ал'йо навчає ученицю таємниць пігментів і священного ритуалу рукопису, створюючи першу з Зур'ашар.",
    ["Witness the First Maldraxxian Armistice."] = "Стань свідком Першого Малдракшіанського перемир'я.",
    ["Witness the ceremonial blessing of Sky's Hope: the stone that fell from the sky after Awe'ohna's flight."] = "Стань свідком урочистого освячення Надії Небес — каменя, що впав із неба після польоту Аве'огни.",
    ["Witness the results of the dark pact forged between The Jailer and The Dark Lady."] = "Поглянь на наслідки темного пакту, укладеного між Тюремником і Темною Володаркою.",
    ["Won't you be a dear and help this little old lady cross the street?"] = "Будь ласкавий, допоможи цій старенькій бабусі перейти вулицю.",
    ["Wooly Wanderers"] = "Кошлаті Мандрівники",
    ["Wooly Warrior"] = "Кошлатий Воїн",
    ["Words failed, and while Russula has a plan, it needs to gather its power so that it can tower over the battlefield, turning sheer size into persuasion."] = "Слова не допомогли, і хоча в Руссули є план, їй треба зібрати силу, щоб височіти над полем бою, обертаючи саму свою велич на переконливість.",
    ["Words of the Wise"] = "Слова Мудрих",
    ["Work with the Horde to find Baine."] = "Працюй разом з Ордою, щоб знайти Бейна.",
    ["Work with your allies to assault Bloodied Crossing."] = "Разом із союзниками штурмуй Закривавлений Перехід.",
    ["Workshop Starting Soon!"] = "Майстерня незабаром розпочнеться!",
    ["Worldsoul Vision"] = "Видіння Світодуші",
    ["Worst. Guard. Ever."] = "Найгірша. Варта. У світі.",
    ["Wort Pulling"] = "Збір сусла",
    ["Wounded Honor"] = "Поранена Честь",
    ["Wounded Murlocs"] = "Поранені Мурлоки",
    ["Wounded Watchers"] = "Поранені Спостерігачі",
    ["Wrath of the Illidari"] = "Гнів Іллідарі",
    ["Wrath of the Jailer"] = "Гнів Тюремника",
    ["Wrath of the Void"] = "Гнів Порожнечі",
    ["Wreck and Break"] = "Трощи і ламай",
    ["Wrecking Clew"] = "Руйнівна Ватага",
    ["Wuho should have located a good spot to start. Wait for his signal, then regroup at the landing site."] = "Вухо вже мав би знайти добре місце для початку. Чекай на його сигнал, а потім перегрупуйся на місці висадки.",
    ["Xylem is draining Azeroth's Ley lines. You must stop him!"] = "Ксайлем висмоктує лей-лінії Азерота. Ти мусиш зупинити його!",
    ["You Are Not Prepared!"] = "Ти не готовий!",
    ["You CAN Go Home"] = "Додому ВЕРНУТИСЯ можна",
    ["You Can Run..."] = "Можеш тікати...",
    ["You Dirty Rat"] = "Ах ти ж паскудний щур",
    ["You Face Jaraxxus"] = "Перед тобою Джаракс",
    ["You Have Your Orders"] = "Накази ти отримав",
    ["You Make Candles"] = "Ти Робиш Свічки",
    ["You Won't Like Us When We're Mad..."] = "Тобі не сподобається, коли ми розлютимося...",
    ["You can catch Clubfish off the north coast of Iskaara."] = "Дубину можна впіймати біля північного узбережжя Іскаари.",
    ["You can catch Grungles off the northeast coast of Iskaara."] = "Ґрунґлів можна впіймати біля північно-східного узбережжя Іскаари.",
    ["You can catch Iceback Sculpin off the northeast coast of Iskaara."] = "Льодоспинного підкам'яника можна впіймати біля північно-східного узбережжя Іскаари.",
    ["You can catch Lakkamuk Blennies off the northeast coast of Iskaara."] = "Лаккамуцьких собачок можна впіймати біля північно-східного узбережжя Іскаари.",
    ["You can catch Manasuckers off the northeast coast of Iskaara."] = "Манасосів можна впіймати біля північно-східного узбережжя Іскаари.",
    ["You can find bones on the leviathan carcass in southwest Iskaara."] = "Кістки можна знайти на туші левіафана на південному заході Іскаари.",
    ["You can obtain Ancheevies near Arv, west of the pot."] = "Анчіві можна роздобути біля Арва, на захід від казана.",
    ["You can purchase Piping-Hot Orca Milk from Tuukanit in Iskaara's central tent."] = "Гаряче-прегаряче молоко косатки можна купити в Туканіта в центральному наметі Іскаари.",
    ["You can purchase a Hunk o' Blubber from Jukarakikk in southwest Iskaara."] = "Шмат ворвані можна купити в Джукаракікка на південному заході Іскаари.",
    ["You can purchase the tea from Nappa, the innkeeper."] = "Чай можна купити в корчмаря Наппи.",
    ["You got past the timer"] = "Ти встиг до закінчення таймера",
    ["You have arrived in the Maelstrom. Speak to Nozdormu to figure out what is next."] = "Ти прибув до Виру. Поговори з Ноздорму, щоб з'ясувати, що далі.",
    ["You have arrived with Eitrigg in the Frostwolf lands. You should follow him to your audience with Drek'thar."] = "Ти прибув з Ейтріґґом до земель Морозних Вовків. Тобі слід піти за ним на аудієнцію до Дрек'Тара.",
    ["You have assembled in Frostwolf Keep with Eitrigg, Thrall, Aggra, and their children. It is time to discuss the return of the Kosh'harg."] = "Ти зібрався у Фортеці Морозних Вовків з Ейтріґґом, Траллом, Аґґрою та їхніми дітьми. Час обговорити повернення Кош'гарґу.",
    ["You have defeated Drek'Thar's wolves, but he is not finished with you yet!"] = "Ти здолав вовків Дрек'Тара, але він іще з тобою не закінчив!",
    ["You have proven yourself worthy of being the first to complete the new rite. It is time to begin preparations for the Kosh'harg!"] = "Ти довів, що гідний першим завершити новий обряд. Час починати приготування до Кош'гарґу!",
    ["You made it through the Portal"] = "Ти пройшов крізь Портал",
    ["You must destroy Kruul permanently in the Twisting Nether before he overruns your forces at the Broken Shore!"] = "Ти мусиш остаточно знищити Круула у Викривленому Нижньому Світі, перш ніж він зімне твої сили на Розколотому Узбережжі!",
    ["You must find the Herald in Stormwind Keep before he summons the Legion into the city!"] = "Ти мусиш знайти Глашатая у Фортеці Стормвінда, перш ніж він прикличе Легіон до міста!",
    ["You must prevent Thermaplugg's missile from launching to the Broken Isles!"] = "Ти мусиш не дати ракеті Термаплаґґа стартувати до Розколотих Островів!",
    ["You must wield Titanstrike so Hati's absorbed power can return to the legendary rifle."] = "Ти мусиш узяти Титанобій, щоб поглинута сила Гаті повернулася до легендарної рушниці.",
    ["You will only have a limited amount of time to gather as much treasure as you can.  Speak to Taoshi when you're ready to begin."] = "У тебе буде обмаль часу, щоб зібрати якнайбільше скарбів. Поговори з Таоші, коли будеш готовий почати.",
    ["You're So Divine"] = "Ти такий божественний",
    ["You've arrived at Shield's Rest. Meet up with Orik and prepare to enter the tomb."] = "Ти прибув до Спочинку Щита. Зустрінься з Оріком і приготуйся увійти до гробниці.",
    ["You've come to the ruins of Falanaar in search of Verstok and the Fangs of Ashamane. Search for clues as to where Verstok has disappeared to."] = "Ти прийшов до руїн Фаланаара в пошуках Верстока та Іклів Ашамане. Шукай підказки, куди зник Версток.",
    ["You've emerged upon a ship of the Burning Legion to find your allies have become seperated in battle. Help Vindicator Boros recover from his injuries."] = "Ти опинився на кораблі Палаючого Легіону й виявив, що твоїх союзників розкидало в бою. Допоможи захиснику Боросу оговтатися від ран.",
    ["You've found Verstok caught in the web of a horrific creature. Slay it."] = "Ти знайшов Верстока, що заплутався в павутині жахливої істоти. Убий її.",
    ["You've weakened the Storm Dragon. Leap upon the beast and use it to reach Typhinius."] = "Ти послабив Штормового Дракона. Стрибни на звіра й дістанься на ньому до Тифінія.",
    ["Your allies have been captured! Rescue them before their souls are corrupted!"] = "Твоїх союзників захопили! Врятуй їх, перш ніж їхні душі осквернять!",
    ["Your allies have gone mad! Save them from each other while stopping Erdris from raising an army of souls."] = "Твої союзники збожеволіли! Врятуй їх одне від одного, водночас не давши Ердрісу зібрати армію душ.",
    ["Your allies seem injured but will move on your command."] = "Твої союзники, схоже, поранені, але рушать за твоїм наказом.",
    ["Your deaths have attracted the Tarragrue! Get to the next floor before he does!"] = "Ваші смерті привабили Тарраґру! Дістаньтеся наступного поверху раніше за нього!",
    ["Your efforts have attracted a large opponent. Deal with them!"] = "Твої зусилля привабили великого супротивника. Розберися з ним!",
    ["Your foes are using the Stormtouched Orbs to empower themselves. Destroy the orbs and break through the Raging Winds."] = "Твої вороги використовують Торкнуті Штормом Сфери, щоб посилитися. Знищ сфери й прорвися крізь Шалені Вітри.",
    ["Your mount was slain. You have landed on the back of a Winged Soul Eater. Grab the reins!"] = "Твою їздову тварину вбито. Ти приземлився на спину Крилатого Пожирача Душ. Хапай повіддя!",
    ["Yrgrim's Challenge"] = "Виклик Ірґріма",
    ["Yrgrim, wielder of the Truthguard has challenged you to a trial by combat. Complete the trial to earn his respect."] = "Ірґрім, носій Вартового Правди, кинув тобі виклик на двобій. Пройди випробування, щоб заслужити його повагу.",
    ["Yu'lon, the Jade Serpent, has been injured! Defend her from the demonic attackers!"] = "Ю'лон, Нефритову Змію, поранено! Захисти її від нападників-демонів!",
    ["Zakajz has been defeated again, but it is not permanent. Take up Strom'kar and deal the final true blow."] = "Закаджза знову здолано, але це ненадовго. Візьми Стром'кар і завдай останнього справжнього удару.",
    ["Zakajz is awake but neither fully healed or fully in control of its mind. Fight it back into unconsciousness!"] = "Закаджз прокинувся, але ще не повністю зцілений і не повністю володіє своїм розумом. Заштовхай його назад у безпам'ятство!",
    ["Zakajz is struggling to defend itself. Draw out the sword and perform the final blow!"] = "Закаджз ледве здатен оборонятися. Витягни меч і завдай останнього удару!",
    ["Zalesx tore across battlefields in a blind rage, leaving only corpses in its wake."] = "Залескс шаленів на полях битв у сліпій люті, лишаючи за собою лише трупи.",
    ["Zandalar coffee beans! Roasts & Boasts could sell this,"] = "Зандаларські кавові зерна! «Roasts & Boasts» могли б це продавати,",
    ["Zaralek Cavern is crawling with Primalists!"] = "Печера Заралек кишить первісниками!",
    ["Zekvir's Lair"] = "Лігво Зеквіра",
    ["Zenith"] = "Зеніт",
    ["Zing'has the Brute"] = "Зінґ'гас Громило",
    ["Zul'Gurub"] = "Зул'Ґуруб",
}
